    25  /**
    26    pull a general string from the wire
    27  */
    28  _PUBLIC_ enum ndr_err_code ndr_pull_string(struct ndr_pull *ndr, int ndr_flags, const char **s)
    29  {
    30          char *as=NULL;
    31          uint32_t len1, ofs, len2;
    32          uint16_t len3;
    33          size_t conv_src_len = 0, converted_size;
    34          int do_convert = 1, chset = CH_UTF16;
    35          unsigned byte_mul = 2;
    36          unsigned flags = ndr->flags;
    37          unsigned c_len_term = 0;
    38
    39          if (!(ndr_flags & NDR_SCALARS)) {
    40                  return NDR_ERR_SUCCESS;
    41          }
    42
    43          if (NDR_BE(ndr)) {
    44                  chset = CH_UTF16BE;
    45          }
    46
    47          if (flags & LIBNDR_FLAG_STR_ASCII) {
    48                  chset = CH_DOS;
    49                  byte_mul = 1;
    50                  flags &= ~LIBNDR_FLAG_STR_ASCII;
    51          }
    52
    53          if (flags & LIBNDR_FLAG_STR_UTF8) {
    54                  chset = CH_UTF8;
    55                  byte_mul = 1;
    56                  flags &= ~LIBNDR_FLAG_STR_UTF8;
    57          }
    58
    59          if (flags & LIBNDR_FLAG_STR_RAW8) {
    60                  do_convert = 0;
    61                  byte_mul = 1;
    62                  flags &= ~LIBNDR_FLAG_STR_RAW8;
    63          }
    64
    65          flags &= ~LIBNDR_FLAG_STR_CONFORMANT;
    66          if (flags & LIBNDR_FLAG_STR_CHARLEN) {
    67                  c_len_term = 1;
    68                  flags &= ~LIBNDR_FLAG_STR_CHARLEN;
    69          }
    70
    71          switch (flags & LIBNDR_STRING_FLAGS) {
    72          case LIBNDR_FLAG_STR_LEN4|LIBNDR_FLAG_STR_SIZE4:
    73          case LIBNDR_FLAG_STR_LEN4|LIBNDR_FLAG_STR_SIZE4|LIBNDR_FLAG_STR_NOTERM:
    74                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &len1));
    75                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &ofs));
    76                  if (ofs != 0) {
    77                          return ndr_pull_error(ndr, NDR_ERR_STRING, "non-zero array offset with string flags 0x%x\n",
    78                                                ndr->flags & LIBNDR_STRING_FLAGS);
    79                  }
    80                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &len2));
    81                  if (len2 > len1) {
    82                          return ndr_pull_error(ndr, NDR_ERR_STRING,
    83                                                "Bad string lengths len1=%u ofs=%u len2=%u\n",
    84                                                len1, ofs, len2);
    85                  } else if (len1 != len2) {
    86                          DEBUG(6,("len1[%u] != len2[%u] '%s'\n", len1, len2, as));
    87                  }
    88                  conv_src_len = len2 + c_len_term;
    89                  break;
    90
    91          case LIBNDR_FLAG_STR_SIZE4:
    92          case LIBNDR_FLAG_STR_SIZE4|LIBNDR_FLAG_STR_NOTERM:
    93                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &len1));
    94                  conv_src_len = len1 + c_len_term;
    95                  break;
    96
    97          case LIBNDR_FLAG_STR_LEN4:
    98          case LIBNDR_FLAG_STR_LEN4|LIBNDR_FLAG_STR_NOTERM:
    99                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &ofs));
   100                  if (ofs != 0) {
   101                          return ndr_pull_error(ndr, NDR_ERR_STRING, "non-zero array offset with string flags 0x%x\n",
   102                                                ndr->flags & LIBNDR_STRING_FLAGS);
   103                  }
   104                  NDR_CHECK(ndr_pull_uint32(ndr, NDR_SCALARS, &len1));
   105                  conv_src_len = len1 + c_len_term;
   106                  break;
   107
   108          case LIBNDR_FLAG_STR_SIZE2:
   109          case LIBNDR_FLAG_STR_SIZE2|LIBNDR_FLAG_STR_NOTERM:
   110                  NDR_CHECK(ndr_pull_uint16(ndr, NDR_SCALARS, &len3));
   111                  conv_src_len = len3 + c_len_term;
   112                  break;
   113
   114          case LIBNDR_FLAG_STR_SIZE2|LIBNDR_FLAG_STR_NOTERM|LIBNDR_FLAG_STR_BYTESIZE:
   115                  NDR_CHECK(ndr_pull_uint16(ndr, NDR_SCALARS, &len3));
   116                  conv_src_len = len3;
   117                  byte_mul = 1; /* the length is now absolute */
   118                  break;
   119
   120          case LIBNDR_FLAG_STR_NULLTERM:
   121                  /*
   122                   * We ensure that conv_str_len cannot return 0 by
   123                   * requring that there be enough bytes for at least
   124                   * the NULL terminator
   125                   */
   126                  if (byte_mul == 1) {
   127                          NDR_PULL_NEED_BYTES(ndr, 1);
   128                          conv_src_len = ascii_len_n((const char *)(ndr->data+ndr->offset), ndr->data_size - ndr->offset);
   129                  } else {
   130                          NDR_PULL_NEED_BYTES(ndr, 2);
   131                          conv_src_len = utf16_len_n(ndr->data+ndr->offset, ndr->data_size - ndr->offset);
   132                  }
   133                  byte_mul = 1; /* the length is now absolute */
   134                  break;
   135
   136          case LIBNDR_FLAG_STR_NOTERM:
   137                  if (!(ndr->flags & LIBNDR_FLAG_REMAINING)) {
   138                          return ndr_pull_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x (missing NDR_REMAINING)\n",
   139                                                ndr->flags & LIBNDR_STRING_FLAGS);
   140                  }
   141                  conv_src_len = ndr->data_size - ndr->offset;
   142                  byte_mul = 1; /* the length is now absolute */
   143                  break;
   144
   145          default:
   146                  return ndr_pull_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x\n",
   147                                        ndr->flags & LIBNDR_STRING_FLAGS);
   148          }
   149
   150          NDR_PULL_NEED_BYTES(ndr, conv_src_len * byte_mul);
   151          if (conv_src_len == 0) {
   152                  as = talloc_strdup(ndr->current_mem_ctx, "");
   153                  converted_size = 0;
   154          } else {
   155                  if (!do_convert) {
   156                          as = talloc_strndup(ndr->current_mem_ctx,
   157                                              (char *)ndr->data + ndr->offset,
   158                                              conv_src_len);
   159                          if (!as) {
   160                                  return ndr_pull_error(ndr, NDR_ERR_ALLOC,
   161                                                        "Failed to talloc_strndup() in RAW8 ndr_string_pull()");
   162                          }
   163                          converted_size = MIN(strlen(as)+1, conv_src_len);
   164                  } else if (!convert_string_talloc(ndr->current_mem_ctx, chset,
   165                                             CH_UNIX, ndr->data + ndr->offset,
   166                                             conv_src_len * byte_mul,
   167                                             (void **)(void *)&as,
   168                                             &converted_size)) {
   169                          return ndr_pull_error(ndr, NDR_ERR_CHARCNV,
   170                                                "Bad character conversion with flags 0x%x", flags);
   171                  }
   172          }
   173
   174          /* this is a way of detecting if a string is sent with the wrong
   175             termination */
   176          if (ndr->flags & LIBNDR_FLAG_STR_NOTERM) {
   177                  if (as && converted_size > 0 && as[converted_size-1] == '\0') {
   178                          DEBUG(6,("short string '%s', sent with NULL termination despite NOTERM flag in IDL\n", as));
   179                  }
   180          } else {
   181                  if (as && converted_size > 0 && as[converted_size-1] != '\0') {
   182                          DEBUG(6,("long string '%s', send without NULL termination (which was expected)\n", as));
   183                  }
   184          }
   185
   186          NDR_CHECK(ndr_pull_advance(ndr, conv_src_len * byte_mul));
   187          *s = as;
   188
   189          return NDR_ERR_SUCCESS;
   190  }
