    10  /**
    11   * Return number of elements in a string including the last (zeroed) element
    12   */
    13  _PUBLIC_ uint32_t ndr_string_length(const void *_var, uint32_t element_size)
    14  {
    15          uint32_t i;
    16          uint8_t zero[4] = {0,0,0,0};
    17          const char *var = (const char *)_var;
    18
    19          for (i = 0; memcmp(var+i*element_size,zero,element_size) != 0; i++);
    20
    21          return i+1;
    22  }
