    24  _PUBLIC_ enum ndr_err_code ndr_check_string_terminator(struct ndr_pull *ndr, uint32_t count, uint32_t element_size)
    25  {
    26          uint32_t i;
    27          uint32_t save_offset;
    28
    29          save_offset = ndr->offset;
    30          NDR_CHECK(ndr_pull_advance(ndr, (count - 1) * element_size));
    31          NDR_PULL_NEED_BYTES(ndr, element_size);
    32
    33          for (i = 0; i < element_size; i++) {
    34                   if (ndr->data[ndr->offset+i] != 0) {
    35                          ndr->offset = save_offset;
    36
    37                          return ndr_pull_error(ndr, NDR_ERR_ARRAY_SIZE, "String terminator not present or outside string boundaries");
    38                   }
    39          }
    40
    41          ndr->offset = save_offset;
    42
    43          return NDR_ERR_SUCCESS;
    44  }
