    46  _PUBLIC_ enum ndr_err_code ndr_pull_charset(struct ndr_pull *ndr, int ndr_flags, const char **var, uint32_t length, uint8_t byte_mul, charset_t chset)
    47  {
    48          size_t converted_size;
    49
    50          if (length == 0) {
    51                  *var = talloc_strdup(ndr->current_mem_ctx, "");
    52                  return NDR_ERR_SUCCESS;
    53          }
    54
    55          if (NDR_BE(ndr) && chset == CH_UTF16) {
    56                  chset = CH_UTF16BE;
    57          }
    58
    59          if ((byte_mul != 0) && (length > UINT32_MAX/byte_mul)) {
    60                  return ndr_pull_error(ndr, NDR_ERR_BUFSIZE, "length overflow");
    61          }
    62          NDR_PULL_NEED_BYTES(ndr, length*byte_mul);
    63
    64          if (!convert_string_talloc(ndr->current_mem_ctx, chset, CH_UNIX,
    65                                     ndr->data+ndr->offset, length*byte_mul,
    66                                     discard_const_p(void *, var),
    67                                     &converted_size))
    68          {
    69                  return ndr_pull_error(ndr, NDR_ERR_CHARCNV,
    70                                        "Bad character conversion");
    71          }
    72          NDR_CHECK(ndr_pull_advance(ndr, length*byte_mul));
    73
    74          return NDR_ERR_SUCCESS;
    75  }
